INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 44, 'theory', 'Quiz: axum');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 44, 0, 'What is the Router in axum from tower''s point of view?', '["Only a path table unrelated to tower", "A Service: it takes a request and asynchronously returns a response", "A separate thread", "A macro"]', 1, 'Router implements tower::Service, so layers, timeouts, and a direct call through oneshot all work.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 44, 1, 'Which extractor may only be placed as the last handler argument?', '["Path", "Query", "Json — it reads the request body, which is consumed once", "State"]', 2, 'The body is read once, so an extractor that consumes it goes last.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 44, 2, 'What does axum return for a request with the wrong method to an existing path?', '["404", "405 Method Not Allowed", "200 with an empty body", "500"]', 1, 'The path is found but the method isn''t registered — that is 405; 404 is when the path isn''t found.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 44, 3, 'How is a path parameter written in axum 0.8?', '["/users/:id", "/users/{id}", "/users/<id>", "/users/$id"]', 1, 'Since version 0.8 curly braces are used; the colon syntax is no longer supported.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 44, 4, 'How can you test a handler without starting a server or opening a port?', '["Only by starting a server on port 8080", "Call the Router as a Service through tower::ServiceExt::oneshot", "It can''t be tested without a browser", "Run curl by hand"]', 1, 'oneshot sends a request into the router in memory, with no sockets; the body is read with to_bytes.');
